"""Self-contained searchable HTML opportunity list."""
import html
import json

from .common import closing_label, eligibility_label, safe_url, source_summaries, status_label


def _e(value): return html.escape(str(value if value is not None else ""), quote=True)
def _items(values): return "; ".join(str(x) for x in (values or [])) or "Not recorded"
def _link(label, url):
    safe = safe_url(url)
    return f'<a href="{_e(safe)}">{_e(label)}</a>' if safe else _e(label)


def render_html(payload):
    rows = payload.get("rows", [])
    def ctx(row):
        r = row["record"]
        return r.get("record_kind", "").endswith("context") or r.get("lifecycle") in {"closed", "awarded", "cancelled", "superseded"}
    rendered = []
    for row in rows:
        r, m = row["record"], row["match"]
        caps = [c.get("id", c.get("name", "")) if isinstance(c, dict) else c for c in r.get("capabilities", [])]
        places = [p.get("name", "") for p in r.get("locations", []) if p.get("role") in {"worksite", "delivery"}]
        elig = m.get("eligibility", {})
        sources = source_summaries(r)
        route = r.get("application_route") or {}
        links = "; ".join(_link(s.get("source_id") or "Source", s.get("url")) + " accessed " + _e(s.get("accessed_at") or "unknown") + ("; licence " + _link("licence", s.get("licence_url")) if s.get("licence_url") else "") for s in sources) or "None recorded"
        route_html = _link(route.get("url") or route.get("email") or "No route published", route.get("url") or ("mailto:" + route["email"] if route.get("email") else None))
        searchable = " ".join([r.get("title", ""), r.get("summary", ""), " ".join(caps), status_label(r), r.get("lifecycle", ""), " ".join(places), elig.get("status", "unknown")]).lower()
        rendered.append(f'''<article class="card" data-context="{str(ctx(row)).lower()}" data-status="{_e(r.get('status_class') or 'context')}" data-life="{_e(r.get('lifecycle','unknown'))}" data-elig="{_e(elig.get('status','unknown'))}" data-place="{'known' if places else 'unknown'}" data-caps="{_e('|'.join(caps))}" data-title="{_e(r.get('title',''))}" data-score="{m.get('score',0)}" data-close="{_e(r.get('close_at_utc') or '9999')}" data-search="{_e(searchable)}">
<h2>{_e(r.get('title','Untitled'))}</h2><p><span class="badge">{_e(status_label(r))}</span> <span class="badge">Lifecycle: {_e(r.get('lifecycle','unknown'))}</span> <span class="badge">Fit: {_e(m.get('score',0))}/100</span> <span class="badge">Eligibility: {_e(elig.get('status','unknown'))}</span></p>
<p><strong>Reason:</strong> {_e(r.get('classification_reason') or 'Not recorded')} <strong>Freshness:</strong> {_e(r.get('freshness_state','unknown'))}; verified {_e(r.get('verified_at') or 'not published')}.</p><p><strong>Stage:</strong> {_e(r.get('procurement_stage','unknown'))}. <strong>Capability:</strong> {_e(_items(caps))}. <strong>Geography:</strong> {_e('; '.join(places) or 'not published')}.</p>
<p><strong>Fit components:</strong> {_e(json.dumps(m.get('components',{}), ensure_ascii=False, sort_keys=True))}. <strong>Matched:</strong> {_e(_items(m.get('matched_capabilities')))}. <strong>Missing:</strong> {_e(_items(m.get('missing_capabilities')))}. <strong>Rationale/evidence:</strong> {_e(_items(m.get('evidence')))}.</p>
<p><strong>Eligibility:</strong> {_e(eligibility_label(m))}. Record requirements: {_e(_items(r.get('eligibility')))}. Constraints: {_e(_items(m.get('exclusions')))}.</p>
<p><strong>Close:</strong> {_e(closing_label(r))} (original: {_e(r.get('close_raw') or 'not published')}).</p>
<p><strong>Official route:</strong> {_e(route.get('purpose','unknown'))}; {route_html}; account required: {_e(route.get('account_required','unknown'))}; instructions: {_e(route.get('instructions') or 'None published')}.</p>
<p><strong>Conditions:</strong> {_e(_items(r.get('conditions')))}</p><details><summary>Evidence, sources and access</summary><p>Summary: {_e(r.get('summary',''))}</p><p>{links}</p><p>Source publication: {_e(r.get('source_published_at') or 'not published')}; verification: {_e(r.get('verified_at') or 'not published')}.</p><p>Attribution: {_e(_items(r.get('attribution')))}</p></details></article>''')
    cov = payload.get("coverage", {})
    open_count = cov.get("confirmed_open", sum(r["record"].get("status_class") == "confirmed_open" for r in rows))
    coverage = cov.get("summary") or f"{cov.get('held',{}).get('total',0)} held; {cov.get('excluded_irrelevant',0)} unrelated excluded."
    data = "\n".join(rendered) or '<p id="empty">No records in this build.</p>'
    return f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Defence supply radar — {_e(payload.get('period',''))}</title><style>
:root{{color-scheme:light;--navy:#102b46;--teal:#087e83;--ink:#182b3a;--paper:#f4f8f8}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,sans-serif}}header{{background:var(--navy);color:white;padding:1.5rem max(1rem,calc((100% - 1100px)/2))}}main{{max-width:1100px;margin:auto;padding:1rem}}h1,h2{{line-height:1.2}}h1{{margin:.2rem 0}}.summary,.controls,.card{{background:white;border:1px solid #c9d9dc;border-radius:.6rem;padding:1rem;margin:.8rem 0}}.table-wrap{{overflow-x:auto}}table{{border-collapse:collapse;min-width:32rem;width:100%}}th,td{{border:1px solid #c9d9dc;padding:.4rem;text-align:left}}.controls{{display:flex;flex-wrap:wrap;gap:.8rem;align-items:end}}label{{display:grid;gap:.2rem;font-weight:600}}input,select,button{{font:inherit;padding:.5rem;border:1px solid #627d89;border-radius:.3rem}}button{{background:var(--teal);color:white;cursor:pointer}}:focus-visible{{outline:3px solid #f2ac42;outline-offset:2px}}.badge{{display:inline-block;background:#e0f3f1;color:#064b50;border:1px solid #8bcac4;border-radius:2rem;padding:.15rem .55rem;margin:.1rem;font-size:.9rem}}a{{color:#075d74}}details{{border-top:1px solid #ddd;padding-top:.5rem}}@media(max-width:600px){{.controls label{{width:100%}}}}</style>
<header><h1>Defence supply radar</h1><p>Period: <strong>{_e(payload.get('period','not specified'))}</strong> · As of {_e(payload.get('as_of','not specified'))}</p></header><main><section class="summary" aria-label="Coverage summary"><h2>Coverage</h2><p><strong>{open_count} confirmed open</strong> · {cov.get('context_records',0)} relevant context records · {_e(coverage)}</p><p>{'No confirmed-open opportunities in this build.' if not open_count else 'Open count reflects verified classified records.'} Context includes awarded history and does not represent current work or an application opportunity.</p></section>
<div class="table-wrap"><table><caption>Build coverage summary</caption><thead><tr><th scope="col">Confirmed open</th><th scope="col">Context records</th><th scope="col">Held</th><th scope="col">Unrelated excluded</th></tr></thead><tbody><tr><td>{open_count}</td><td>{cov.get("context_records",0)}</td><td>{cov.get("held",{}).get("total",0)}</td><td>{cov.get("excluded_irrelevant",0)}</td></tr></tbody></table></div>
<noscript><p>JavaScript is off; all records are shown below. The list is still readable, but search and filters need JavaScript.</p></noscript><section class="controls" aria-label="Search and filters"><label>Search<input id="q" type="search" aria-label="Search records"></label><label>Capability<select id="cap"><option value="">All capabilities</option></select></label><label>Status<select id="status"><option value="">All statuses</option><option value="confirmed_open">Confirmed open</option><option value="published_future_scope">Published future scope</option><option value="speculative">Speculative</option><option value="context">Context</option></select></label><label>Lifecycle<select id="life"><option value="">All lifecycles</option></select></label><label>Geography<select id="geo"><option value="">All geography</option><option value="known">Known</option><option value="unknown">Unknown</option></select></label><label>Eligibility<select id="elig"><option value="">All eligibility</option><option value="meets_known_requirements">Meets known requirements (not approval)</option><option value="does_not_meet">Does not meet a mandatory requirement</option><option value="unknown">Unknown</option></select></label><label>View<select id="view"><option value="active">Active only</option><option value="all">All records including context/inactive/speculative</option></select></label><label>Sort<select id="sort"><option value="fit">Best fit</option><option value="title">Title</option><option value="close">Closing date</option></select></label><button id="clear" type="button">Clear filters</button><span id="count" aria-live="polite"></span></section><p id="reveal" hidden>No active matches. <button id="showall" type="button">Show context, inactive and speculative records</button></p><section id="results" aria-label="Records">{data}</section></main>
<script>''' + r'''(()=>{const cards=[...document.querySelectorAll('.card')],ids=['q','cap','status','life','geo','elig','view','sort'],els=Object.fromEntries(ids.map(x=>[x,document.getElementById(x)]));const caps=new Set(),lives=new Set();cards.forEach(c=>{c.dataset.caps.split('|').filter(Boolean).forEach(x=>caps.add(x));lives.add(c.dataset.life)});for(const [set,id] of [[caps,'cap'],[lives,'life']])set.forEach(x=>{const o=document.createElement('option');o.value=x;o.textContent=x;els[id].append(o)});function update(){const q=els.q.value.toLowerCase();let active=0,shown=0;cards.forEach(c=>{const isActive=['confirmed_open','published_future_scope'].includes(c.dataset.status);if(isActive)active++;const ok=(els.view.value==='all'||(c.dataset.context==='false'&&isActive))&&(!q||c.dataset.search.includes(q))&&(!els.cap.value||c.dataset.caps.split('|').includes(els.cap.value))&&(!els.status.value||c.dataset.status===els.status.value)&&(!els.life.value||c.dataset.life===els.life.value)&&(!els.geo.value||c.dataset.place===els.geo.value)&&(!els.elig.value||c.dataset.elig===els.elig.value);c.hidden=!ok;if(ok)shown++});const list=document.getElementById('results');[...cards].sort((a,b)=>els.sort.value==='title'?a.dataset.title.localeCompare(b.dataset.title):els.sort.value==='close'?a.dataset.close.localeCompare(b.dataset.close):Number(b.dataset.score)-Number(a.dataset.score)).forEach(c=>list.append(c));document.getElementById('count').textContent=shown+' of '+cards.length+' records';document.getElementById('reveal').hidden=!(cards.length&&shown===0&&els.view.value==='active');}ids.forEach(id=>els[id].addEventListener('input',update));document.getElementById('clear').onclick=()=>{ids.forEach(id=>els[id].value=id==='view'?'active':id==='sort'?'fit':'');update()};document.getElementById('showall').onclick=()=>{els.view.value='all';update()};update()})();''' + r'''</script></html>'''
